#!/usr/bin/env node
/**
 * reconcile-sitemap-orphans.mjs — sweep dist/ for indexable HTML pages that are
 * NOT present in any generated sub-sitemap, and emit them as sitemap-orphans.xml.
 *
 * Fixes the data-drift orphan problem: generate-sitemap.ts builds the sitemap
 * from src/data/* imports, so any page whose data entry was renamed/removed (or
 * was generated by a step that predates the data-driven sitemap) silently drops
 * out of the sitemap while remaining live and indexable. This script guarantees
 * the sitemap covers every indexable page actually present in the build output.
 *
 * Served-URL filter: this site is NOT cleanUrls — flat `x.html` files are only
 * reachable at their clean URL when a vercel.json rewrite maps `/cluster/:slug`
 * to `/cluster/:slug.html`. Directory pages (`x/index.html`) are served by the
 * static directory-index default. Flat files with no matching rewrite 404 at
 * the clean URL (stale build artifacts) and must be excluded. We parse
 * vercel.json rewrites and drop any flat page whose clean URL has no rewrite.
 *
 * Runs AFTER all page generation (post-prerender), BEFORE generate:site-index so
 * the discovery hub picks it up. Idempotent — safe to run repeatedly.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, relative } from "node:path";

const CWD = process.cwd();
const DIST = join(CWD, "dist");
const BASE = "https://invisibleexit.com";

if (!existsSync(DIST)) {
  console.log("(no dist/ — skipping orphan reconcile)");
  process.exit(0);
}

const SKIP_DIRS = new Set([
  ".well-known", "assets", "og", ".vercel", ".git", "node_modules", "_next",
]);
const SKIP_NAMES = new Set(["404.html"]);

// --- vercel.json rewrite → served clean-URL matcher (flat .html files only) ---
function buildRewriteMatchers() {
  const vjPath = join(CWD, "vercel.json");
  if (!existsSync(vjPath)) return [];
  let cfg;
  try {
    cfg = JSON.parse(readFileSync(vjPath, "utf8"));
  } catch {
    return [];
  }
  const out = [];
  for (const r of cfg.rewrites || []) {
    const src = r.source;
    if (!src || src.startsWith("^") || src.includes("$")) continue; // skip anchors, unusual
    let s = src;
    // tokenize path-to-regexp constructs before escaping
    s = s.replace(/:[\w]+\*/g, "\u0001W\u0001").replace(/\(\.\*\)/g, "\u0001W\u0001");
    s = s.replace(/:[\w]+/g, "\u0001S\u0001");
    s = s.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
    s = s.replace(/\u0001W\u0001/g, ".*").replace(/\u0001S\u0001/g, "[^/]+");
    try {
      out.push(new RegExp("^" + s + "$"));
    } catch {
      /* skip malformed */
    }
  }
  return out;
}
const REWRITES = buildRewriteMatchers();
const hasRewrite = (urlPath) => REWRITES.some((re) => re.test(urlPath));

function isNoindex(html) {
  const m =
    html.match(/<meta[^>]+name=["']robots["'][^>]+content=["']([^"']+)["']/i) ||
    html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']robots["']/i);
  return m ? /noindex/i.test(m[1]) : false;
}

const norm = (s) => (s === "/" ? "/" : s.replace(/\/+$/, ""));

// 1. Collect every indexable, *served* page in dist/.
const indexable = new Set();
function walk(dir) {
  for (const ent of readdirSync(dir, { withFileTypes: true })) {
    if (ent.name.startsWith(".") || SKIP_DIRS.has(ent.name)) continue;
    if (ent.isDirectory()) {
      walk(join(dir, ent.name));
      continue;
    }
    if (!ent.name.endsWith(".html")) continue;
    if (SKIP_NAMES.has(ent.name)) continue;
    if (ent.name.startsWith("sitemap")) continue;
    if (/^google[a-f0-9]+\.html$/i.test(ent.name)) continue;

    const abs = join(dir, ent.name);
    const rel = relative(DIST, abs).replace(/\\/g, "/");
    const isDirIndex = rel.endsWith("/index.html") || rel === "index.html";
    let clean;
    if (rel === "index.html") clean = "/";
    else clean = "/" + rel.replace(/\/index\.html$/, "").replace(/\.html$/, "");
    clean = norm(clean);

    // Served-URL gate: directory pages always served; flat files need a rewrite.
    if (!isDirIndex && !hasRewrite(clean)) continue;

    let html;
    try {
      html = readFileSync(abs, "utf8").slice(0, 16384);
    } catch {
      continue;
    }
    if (isNoindex(html)) continue;
    indexable.add(clean);
  }
}
walk(DIST);

// 2. Collect every URL already referenced by any sub-sitemap in dist/.
//    (Exclude sitemap-orphans.xml itself — it is the file we regenerate.)
const existing = new Set();
for (const f of readdirSync(DIST)) {
  if (f === "sitemap-orphans.xml") continue;
  if (!/^sitemap-.*\.xml$/.test(f) && f !== "image-sitemap.xml") continue;
  let body;
  try {
    body = readFileSync(join(DIST, f), "utf8");
  } catch {
    continue;
  }
  for (const m of body.matchAll(/<loc>\s*(.*?)\s*<\/loc>/g)) {
    const u = m[1].replace(BASE, "").trim();
    existing.add(u === "" || u === "/" ? "/" : norm(u));
  }
}

const orphans = [...indexable].filter((p) => !existing.has(p)).sort();

if (orphans.length === 0) {
  console.log("✓ 0 orphan pages — sitemaps already complete");
  process.exit(0);
}

const today = new Date().toISOString().slice(0, 10);
const xml =
  '<?xml version="1.0" encoding="UTF-8"?>\n' +
  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
  orphans
    .map((p) => `  <url>\n    <loc>${BASE}${p === "/" ? "/" : p}</loc>\n    <lastmod>${today}</lastmod>\n  </url>`)
    .join("\n") +
  "\n</urlset>\n";

writeFileSync(join(DIST, "sitemap-orphans.xml"), xml, "utf8");
console.log(`✓ wrote sitemap-orphans.xml: ${orphans.length} orphaned indexable pages recovered`);
